import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {licensePolicyRoute} from './license-policy-route'
import {TextInput, PageHeader, Button} from '@primer/react'
import {Dialog, Blankslate} from '@primer/react/experimental'
import {LawIcon, SearchIcon, PlusIcon} from '@primer/octicons-react'
import {useState, useMemo} from 'react'
import styles from './LicensePolicy.module.css'
import {useMutation} from '@github-ui/react-query'
import {useRouteParams} from '@github-ui/react-core/future/use-route-params'
import type {EnterprisePolicy} from './types'
import {updateEnterprisePolicy} from './api'

export function LicensePolicy() {
  // Get license policy payload from the route
  // TODO: Add support for dynamically updating the payload to prevent stale data
  const payload = useRouteQuery(licensePolicyRoute, 'mainQuery')
  // Get the business identifier from URL parameters
  const {business} = useRouteParams(licensePolicyRoute)

  const [filterText, setFilterText] = useState('')
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [newLicense, setNewLicense] = useState('')

  // Handler for updating the new license input value
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setNewLicense(e.target.value)
  }

  // Handler for updating the license filter text
  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFilterText(e.target.value)
  }

  // Mutation for creating enterprise policy
  const enterprisePolicyMutation = useMutation({
    mutationFn: (variables: {pathname: string; policy: EnterprisePolicy}) => updateEnterprisePolicy(variables),
    // Clear input and close dialog after a successful mutation (api call)
    onSuccess: () => {
      setNewLicense('')
      setIsDialogOpen(false)
    },
  })

  // Handler for creating an enterprise policy with new license
  // TODO: Add support for creating a policy with pre-existing licenses, since edit API doesn't exist
  const handleAddLicense = () => {
    const policy: EnterprisePolicy = {
      enterprise_id: payload.data.enterprise_id,
      licenses: {
        // TODO: Add support for contexts, for now use placeholder values
        allowed: [{spdx_id: newLicense, contexts: ['distributed', 'network', 'internal']}],
      },
    }
    const pathname = licensePolicyRoute.generatePath({business})
    enterprisePolicyMutation.mutate({
      pathname,
      policy,
    })
  }

  // Updates allowed licenses (filtered licenses) list when filter text changes
  const filteredLicenses = useMemo(() => {
    if (!filterText.trim()) return payload.data.allowed
    return payload.data.allowed.filter(license => license.toLowerCase().includes(filterText.toLowerCase()))
  }, [filterText, payload.data.allowed])

  return (
    <>
      {/* Main page header with title and description */}
      <PageHeader hasBorder role="banner" aria-label="License Policy">
        <PageHeader.TitleArea>
          <PageHeader.Title as="h2" className="h1-override-shared-component">
            License Policy
          </PageHeader.Title>
        </PageHeader.TitleArea>
      </PageHeader>

      <PageHeader.Description className="color-fg-muted mb-4">
        This license policy will only apply to repositories with GitHub Advanced Security and license policy enforcement
        enabled across all organizations in this enterprise. Learn more about license policies
      </PageHeader.Description>

      {/* Section header for allowed licenses with add button */}
      <PageHeader role="banner" aria-label="Allowed Licenses">
        <PageHeader.TitleArea>
          <PageHeader.Title as="h2" className="h1-override-shared-component">
            Allowed Licenses
          </PageHeader.Title>
        </PageHeader.TitleArea>
        <PageHeader.Actions>
          {/* Button to open the add license dialog */}
          <Button leadingVisual={PlusIcon} onClick={() => setIsDialogOpen(!isDialogOpen)}>
            Add licenses
          </Button>
        </PageHeader.Actions>
      </PageHeader>

      {/* Modal dialog for adding new license */}
      {isDialogOpen && (
        <Dialog title="Add licenses" onClose={() => setIsDialogOpen(false)}>
          <div className="p-3">
            <TextInput
              block
              value={newLicense}
              onChange={handleInputChange}
              aria-label="License name"
              placeholder="Enter a license name"
              className="mb-3"
            />
          </div>
          <Dialog.Footer>
            <Button onClick={() => setIsDialogOpen(false)}>Cancel</Button>
            <Button variant="primary" onClick={handleAddLicense}>
              Add
            </Button>
          </Dialog.Footer>
        </Dialog>
      )}

      <PageHeader.Description className="color-fg-muted mb-3">
        Dependencies with these licenses can be used in all repositories in your enterprise without review.
      </PageHeader.Description>

      {/* Search input for filtering licenses */}
      <TextInput
        leadingVisual={SearchIcon}
        type="text"
        placeholder="Search or filter"
        aria-label="Search or filter"
        className="mb-3"
        block
        value={filterText}
        onChange={handleFilterChange}
      />

      {/* Conditional rendering based on whether there are any allowed licenses */}
      {payload.data.allowed.length === 0 ? (
        <Blankslate border>
          <Blankslate.Visual>
            <LawIcon size="medium" />
          </Blankslate.Visual>
          <Blankslate.Heading>Manage allowed licenses</Blankslate.Heading>
          <Blankslate.Description>
            Select which licenses on your dependencies can be used without review
          </Blankslate.Description>
        </Blankslate>
      ) : (
        <ul className="Box list-style-none" data-testid="license-list">
          <div className="Box-header d-flex flex-items-center">
            <h3 className="Box-title">
              {`${filteredLicenses.length} ${filteredLicenses.length === 1 ? 'license' : 'licenses'}`}
            </h3>
          </div>
          {filteredLicenses.map(license => (
            <li key={license} className={styles.listItem}>
              <div className="p-2">
                <div className="d-flex flex-items-center">
                  <LawIcon className="mr-2 color-fg-muted" />
                  <h2 className="f4 text-semibold">{license}</h2>
                </div>
                <p className="color-fg-muted f6 ml-4">{`Added ${payload.data.date_added}`}</p>
              </div>
            </li>
          ))}
          {/* Show message when filter returns no results */}
          {filteredLicenses.length === 0 && <li className="p-3 color-fg-muted">No licenses match your filter</li>}
        </ul>
      )}
    </>
  )
}

try{ LicensePolicy.displayName ||= 'LicensePolicy' } catch {}