import {reactFetchJSON} from '@github-ui/verified-fetch'
import type {EnterprisePolicy} from './types'

export async function updateEnterprisePolicy({pathname, policy}: {pathname: string; policy: EnterprisePolicy}) {
  const init = {
    method: 'POST',
    body: {
      enterprise_id: policy.enterprise_id,
      licenses: policy.licenses,
    },
  }

  const response = await reactFetchJSON(pathname, init)
  if (!response.ok) {
    throw new Error(`Failed to update policy: ${response.statusText}`)
  }
  return response.json()
}
