import {mainQuery} from '@github-ui/react-core/future/main-query'
import {licensePolicyAppBuilder} from '../config/app-builder'

export type LicensePolicyResponse = {
  enterprise_id: number
  allowed: string[]
  date_added: string
}

export const licensePolicyRoute = licensePolicyAppBuilder.createQueryRouteConfig('licensePolicyRoute', {
  path: '/enterprises/:business/settings/advanced_security/license_policy',
  queries: [mainQuery<LicensePolicyResponse>()],
})
